INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Support-Dokumente ohne FAQs nutzlos?', 2, '[{"text": "Nein", "correct": true, "because": "Handbücher ergänzen"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Support-Dokumenten?', 3, '[{"text": "Problemlösung", "correct": true, "because": "Hilft Nutzern direkt"}, {"text": "Code-Optimierung", "correct": false, "because": "Entwicklerfokus"}, {"text": "Marketing", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören in Support-Dokumente?', 5, '[{"text": "FAQs", "correct": true, "because": "Häufige Fragen klären"}, {"text": "Fehlerbehebung", "correct": true, "because": "Löst Probleme"}, {"text": "Design-Spezifikation", "correct": false, "because": "Nicht nutzerrelevant"}, {"text": "Lange Theorien", "correct": false, "because": "Zu komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Support-Dokumente brauchen Struktur. b) Sie ersetzen Schulungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Support-Dokumenten?', 4, '[{"text": "Klarheit", "correct": false, "because": "Essenziell für Nutzer"}, {"text": "Relevanz", "correct": false, "because": "Muss Probleme adressieren"}, {"text": "Code-Beispiele", "correct": true, "because": "Für Devs, nicht Nutzer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Support-Dokumente immer gedruckt sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Digital üblich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für Support-Dokumente?', 3, '[{"text": "Online-FAQs", "correct": true, "because": "Schnell zugänglich"}, {"text": "Papierhandbuch", "correct": false, "because": "Weniger flexibel"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Support-Dokumente effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Verständnis fördern"}, {"text": "Aktualität", "correct": true, "because": "Relevanz sichern"}, {"text": "Technische Tiefe", "correct": false, "because": "Nicht für Laien"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Qualitätsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Support-Dokumente sind nur für Anfänger. b) Sie brauchen Updates. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Alle nutzen, Updates nötig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Support-Dokumente?', 4, '[{"text": "Fehlerlösungen", "correct": false, "because": "Kern der Hilfe"}, {"text": "Beispiele", "correct": false, "because": "Veranschaulichung"}, {"text": "Entwickler-Logs", "correct": true, "because": "Nicht nutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Support-Dokumente nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware möglich"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für FAQs entscheidend?', 4, '[{"text": "Fragen", "correct": true, "because": "Adressieren Probleme"}, {"text": "Antworten", "correct": true, "because": "Lösungen bieten"}, {"text": "Code-Snippets", "correct": false, "because": "Zu technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Support-Dokumente einmalig erstellt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Updates nötig"}, {"text": "Ja", "correct": false, "because": "Wissen veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Support-Dokumenten?', 3, '[{"text": "Verständlichkeit", "correct": true, "because": "Nutzerfokus"}, {"text": "Technische Details", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Support-Dokumente brauchen Beispiele. b) Sie sind nur online nützlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch offline möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gutes Support-Dokument?', 5, '[{"text": "Selbsthilfe", "correct": true, "because": "Nutzer lösen Probleme"}, {"text": "Zeitersparnis", "correct": true, "because": "Weniger Supportanfragen"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Support-Dokumenten unwichtig?', 3, '[{"text": "Struktur", "correct": false, "because": "Gibt Orientierung"}, {"text": "Relevanz", "correct": false, "because": "Muss Probleme lösen"}, {"text": "Schriftfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Support-Dokumente den Support?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Ja", "correct": false, "because": "Support bleibt nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Support-Dokumente technisch sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzerfreundlich wichtiger"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Support-Dokumente entscheidend?', 4, '[{"text": "Suchbarkeit", "correct": true, "because": "Schneller Zugriff"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt Nutzer"}, {"text": "Manuelle Updates", "correct": false, "because": "Nicht primär"}]');
